// UTM TAGGING VALIDATION
const utmData = $('GA4 - UTM data').all();

let issues = [];
let totalSessions = 0;
let organicDirectSessions = 0;
let untaggedSessions = 0;
let partialTaggedSessions = 0;
let wellTaggedSessions = 0;

for (const item of utmData) {
  const row = item.json;
  const source = (row.sessionSource || '').toLowerCase();
  const medium = (row.sessionMedium || '').toLowerCase();
  const campaign = (row.sessionCampaignName || '').toLowerCase();
  const sessions = parseInt(row.sessions || 0);

  totalSessions += sessions;

  const isOrganic = medium === 'organic' || medium === '(none)' || source === '(direct)';
  if (isOrganic) {
    organicDirectSessions += sessions;
    continue;
  }

  if (!source || source === '(not set)' || source === '(none)') {
    issues.push(`Missing UTM source — ${sessions} sessions`);
    untaggedSessions += sessions;
    continue;
  }

  if (!medium || medium === '(not set)' || medium === '(none)') {
    issues.push(`Source "${source}" has no UTM medium — ${sessions} sessions`);
    partialTaggedSessions += sessions;
    continue;
  }

  const paidMediums = ['cpc', 'ppc', 'paid', 'paidsearch', 'paid_search', 'social_paid'];
  if (paidMediums.includes(medium) && (!campaign || campaign === '(not set)')) {
    issues.push(`Paid traffic from "${source}/${medium}" has no campaign name — ${sessions} sessions`);
    partialTaggedSessions += sessions;
    continue;
  }

  wellTaggedSessions += sessions;
}

issues = [...new Set(issues)].slice(0, 10);

const trackableSessions = wellTaggedSessions + untaggedSessions + partialTaggedSessions;
const utmHealthScore = trackableSessions > 0 
  ? Math.round((wellTaggedSessions / trackableSessions) * 100) 
  : 100;

return [{
  json: {
    utm_health_score: utmHealthScore,
    total_sessions: totalSessions,
    organic_direct_sessions: organicDirectSessions,
    trackable_sessions: trackableSessions,
    well_tagged_sessions: wellTaggedSessions,
    untagged_sessions: untaggedSessions,
    partially_tagged_sessions: partialTaggedSessions,
    issues_found: issues.length,
    issues_list: issues,
    status: utmHealthScore >= 90 ? 'Healthy' : utmHealthScore >= 70 ? 'Needs Attention' : 'Critical'
  }
}];

// PREPARE OUTPUT — Build Slack text + Audio script (with SegMetrics)

let aiData;
const rawText = $json.output || $json.text || '';

try {
  const cleaned = rawText.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/\s*```$/, '').trim();
  aiData = JSON.parse(cleaned);
} catch (e) {
  const match = rawText.match(/\{[\s\S]*\}/);
  if (match) aiData = JSON.parse(match[0]);
  else throw new Error('Could not parse AI output: ' + rawText.substring(0, 200));
}

// DATE FORMATTER: "2026-05-08 to 2026-05-14" → "8 May 2026 to 14 May 2026"
function formatDateRange(dateRange) {
  const months = ['January', 'February', 'March', 'April', 'May', 'June',
                  'July', 'August', 'September', 'October', 'November', 'December'];
  function formatSingle(d) {
    const p = d.trim().split('-');
    if (p.length !== 3) return d;
    return `${parseInt(p[2])} ${months[parseInt(p[1]) - 1]} ${p[0]}`;
  }
  if (dateRange.includes(' to ')) {
    const [s, e] = dateRange.split(' to ');
    return `${formatSingle(s)} to ${formatSingle(e)}`;
  }
  return formatSingle(dateRange);
}

const formattedWeekRange = formatDateRange(aiData.week_range);

function growthBadge(growth) {
  if (!growth) return '';
  const isNeg = growth.includes('-');
  const isFlat = growth === '0%' || growth === '+0.0%' || growth === '-0.0%';
  if (isFlat) return ` \`${growth}\``;
  return isNeg ? `  \`${growth}\`` : `  \`${growth}\``;
}

const divider = '\n━━━━━━━━━━━━━━━━━━━━━━━━━━━\n';

// ============ SLACK TEXT ============
let msg = '';
msg += `  *Weekly Performance Brief — ${aiData.client_name}*\n`;
msg += `  _${formattedWeekRange}_`;
msg += divider;

msg += `  *Headline*\n${aiData.headline}`;
msg += divider;

msg += `  *Business Metrics*\n`;
for (const m of aiData.business_metrics) {
  msg += `• *${m.label}:* ${m.value}${growthBadge(m.growth)}\n`;
}
msg = msg.trimEnd();
msg += divider;

msg += `  *Traffic & Search Metrics*\n`;
for (const m of aiData.traffic_metrics) {
  msg += `• *${m.label}:* ${m.value}${growthBadge(m.growth)}\n`;
}
msg = msg.trimEnd();
msg += divider;

msg += `  *What's Working*\n`;
for (const w of aiData.whats_working) msg += `• ${w}\n`;
msg = msg.trimEnd();
msg += '\n\n';

msg += `  *What's Not Working*\n`;
for (const w of aiData.whats_not_working) msg += `• ${w}\n`;
msg = msg.trimEnd();
msg += divider;

msg += `  *Top Revenue Channels*\n`;
aiData.top_revenue_channels.forEach((c, i) => {
  msg += `${i+1}. *${c.channel}* — ${c.leads} leads → ${c.revenue} (${c.conversion_rate} conv)\n`;
});
msg = msg.trimEnd();
msg += '\n\n';

msg += `  *Top Products by Revenue*\n`;
aiData.top_products.forEach((p, i) => {
  msg += `${i+1}. *${p.product}* — ${p.customers} customers → ${p.revenue}\n`;
});
msg = msg.trimEnd();
msg += '\n\n';

msg += `  *Top Search Queries*\n`;
aiData.top_queries.forEach((q, i) => {
  msg += `${i+1}. \`${q.query}\` — ${q.clicks} clicks (pos ${q.position})\n`;
});
msg = msg.trimEnd();
msg += '\n\n';

msg += `  *Top Landing Pages*\n`;
aiData.top_pages.forEach((p, i) => {
  msg += `${i+1}. \`${p.path}\` — ${p.clicks} clicks\n`;
});
msg = msg.trimEnd();
msg += divider;

if (aiData.ads_summary && aiData.ads_summary.spend) {
  msg += `  *Ad Spend Summary*\n`;
  msg += `• *Spend:* ${aiData.ads_summary.spend}\n`;
  msg += `• *Impressions:* ${aiData.ads_summary.impressions} • *Clicks:* ${aiData.ads_summary.clicks}\n`;
  if (aiData.ads_summary.note) msg += `• _${aiData.ads_summary.note}_\n`;
  msg = msg.trimEnd();
  msg += divider;
}

msg += `  *UTM Tracking Health*\n`;
msg += `• *Score:* ${aiData.utm_health.score} _(${aiData.utm_health.status})_\n`;
msg += `• *Tagged correctly:* ${aiData.utm_health.well_tagged} of ${aiData.utm_health.trackable} trackable sessions\n\n`;
msg += `*Issues:*\n`;
for (const i of aiData.utm_health.issues) msg += `• ${i}\n`;
msg = msg.trimEnd();
msg += divider;

msg += `  *Priority Actions This Week*\n`;
aiData.priority_actions.forEach((a, i) => {
  msg += `${i+1}. ${a}\n`;
});
msg = msg.trimEnd();
msg += divider;

msg += `  _Audio version of this brief is attached below_\n`;
msg += `_Generated by Incrementors Analytics • ${new Date().toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' })}_`;

// ============ AUDIO SCRIPT ============
function cleanGrowth(g) {
  if (!g) return '';
  const isNeg = g.includes('-');
  const pct = g.replace(/[+\-%]/g, '');
  return isNeg ? `down ${pct} percent` : `up ${pct} percent`;
}

let script = '';
script += `Hello, here's your weekly performance brief for ${aiData.client_name}, covering ${formattedWeekRange}. `;
script += `${aiData.headline} `;

script += `Starting with the business metrics. `;
aiData.business_metrics.forEach(m => {
  const v = m.value.replace(/\$/g, '').replace(/,/g, '');
  const isRevenue = m.label.toLowerCase().includes('revenue') || m.label.toLowerCase().includes('value');
  if (isRevenue) {
    script += `${m.label} was ${v} dollars, ${cleanGrowth(m.growth)} from last week. `;
  } else {
    script += `${m.label} was ${m.value.replace(/,/g, '')}, ${cleanGrowth(m.growth)} from last week. `;
  }
});

script += `For traffic and search, `;
aiData.traffic_metrics.forEach((m, i) => {
  script += `${m.label} was ${m.value.replace(/,/g, '')}, ${cleanGrowth(m.growth)}`;
  script += i < aiData.traffic_metrics.length - 1 ? '. ' : '. ';
});

script += `On the positive side, `;
aiData.whats_working.forEach((w, i) => {
  script += `${w}${i < aiData.whats_working.length - 1 ? '. Also, ' : '. '}`;
});

script += `However, there are areas of concern. `;
aiData.whats_not_working.forEach((w) => {
  script += `${w}. `;
});

script += `Looking at top revenue channels, `;
const topCh = aiData.top_revenue_channels;
script += `${topCh[0].channel} led with ${topCh[0].leads} leads generating ${topCh[0].revenue.replace(/\$/g, '').replace(/,/g, '')} dollars, `;
script += `followed by ${topCh[1].channel} with ${topCh[1].leads} leads, `;
script += `and ${topCh[2].channel} with ${topCh[2].leads} leads. `;

script += `The top revenue product was ${aiData.top_products[0].product.replace(/\$/g, 'dollar ')}, `;
script += `with ${aiData.top_products[0].customers} customers generating ${aiData.top_products[0].revenue.replace(/\$/g, '').replace(/,/g, '')} dollars. `;

script += `In organic search, the top queries were ${aiData.top_queries[0].query} with ${aiData.top_queries[0].clicks} clicks, `;
script += `and ${aiData.top_queries[1].query} with ${aiData.top_queries[1].clicks} clicks. `;

script += `On tracking health, the UTM score is ${aiData.utm_health.score}, status ${aiData.utm_health.status}. `;
script += `${aiData.utm_health.well_tagged} out of ${aiData.utm_health.trackable} trackable sessions are tagged correctly. `;

script += `Priority actions for this week: `;
aiData.priority_actions.forEach((a, i) => {
  script += `Number ${i+1}, ${a} `;
});

script += `That concludes this week's brief. Have a productive week ahead.`;
script = script.replace(/[*_`~]/g, '').replace(/\s+/g, ' ').trim();

return [{
  json: {
    slack_summary: msg,
    audio_script: script,
    raw_ai: aiData,
    generated_at: new Date().toISOString()
  }
}];

// AGGREGATE ALL DATA — GA4 + GSC + SegMetrics
const config = $('Set client config').first().json;

// ============ GA4 CURRENT WEEK ============
const ga4CurrentRows = $('GA4 - This week').all();
const ga4Current = ga4CurrentRows.reduce((acc, item) => {
  const r = item.json;
  acc.totalUsers += parseInt(r.totalUsers || 0);
  acc.newUsers += parseInt(r.newUsers || 0);
  acc.sessions += parseInt(r.sessions || 0);
  acc.screenPageViews += parseInt(r.screenPageViews || 0);
  acc.eventCount += parseInt(r.eventCount || 0);
  acc.conversions += parseFloat(r.conversions || 0);
  acc.userEngagementDuration += parseFloat(r.userEngagementDuration || 0);
  acc._engagementRateSum += parseFloat(r.engagementRate || 0);
  acc._bounceRateSum += parseFloat(r.bounceRate || 0);
  acc._rowCount += 1;
  return acc;
}, { totalUsers:0, newUsers:0, sessions:0, screenPageViews:0, eventCount:0, conversions:0, userEngagementDuration:0, _engagementRateSum:0, _bounceRateSum:0, _rowCount:0 });

ga4Current.engagementRate = ga4Current._rowCount > 0 ? (ga4Current._engagementRateSum / ga4Current._rowCount) : 0;
ga4Current.bounceRate = ga4Current._rowCount > 0 ? (ga4Current._bounceRateSum / ga4Current._rowCount) : 0;
delete ga4Current._engagementRateSum;
delete ga4Current._bounceRateSum;
delete ga4Current._rowCount;

// ============ GA4 PREVIOUS WEEK ============
const ga4PrevRows = $('GA4 - Last week').all();
const ga4Previous = ga4PrevRows.reduce((acc, item) => {
  const r = item.json;
  acc.totalUsers += parseInt(r.totalUsers || 0);
  acc.newUsers += parseInt(r.newUsers || 0);
  acc.sessions += parseInt(r.sessions || 0);
  acc.screenPageViews += parseInt(r.screenPageViews || 0);
  acc.eventCount += parseInt(r.eventCount || 0);
  acc.conversions += parseFloat(r.conversions || 0);
  return acc;
}, { totalUsers:0, newUsers:0, sessions:0, screenPageViews:0, eventCount:0, conversions:0 });

// ============ GA4 CHANNELS ============
const channels = $('GA4 - Traffic channels').all().map(i => ({
  channel: i.json.sessionPrimaryChannelGroup,
  users: parseInt(i.json.totalUsers || 0),
  sessions: parseInt(i.json.sessions || 0),
  conversions: parseFloat(i.json.conversions || 0)
})).sort((a,b) => b.sessions - a.sessions);

// ============ HELPER: GROWTH % ============
function growth(current, previous) {
  if (!previous || previous === 0) return current > 0 ? '+100%' : '0%';
  const pct = ((current - previous) / previous) * 100;
  return (pct >= 0 ? '+' : '') + pct.toFixed(1) + '%';
}

// ============ GSC CURRENT ============
const gscCurrentRaw = $('GSC - This week').first().json;
const gscCurrentRows = gscCurrentRaw.rows || [];
const gscCurrent = gscCurrentRows.reduce((acc, r) => {
  acc.clicks += r.clicks || 0;
  acc.impressions += r.impressions || 0;
  acc._ctrSum += r.ctr || 0;
  acc._positionSum += r.position || 0;
  acc._count += 1;
  return acc;
}, { clicks:0, impressions:0, _ctrSum:0, _positionSum:0, _count:0 });
gscCurrent.ctr = gscCurrent._count > 0 ? (gscCurrent._ctrSum / gscCurrent._count) : 0;
gscCurrent.position = gscCurrent._count > 0 ? (gscCurrent._positionSum / gscCurrent._count) : 0;
delete gscCurrent._ctrSum;
delete gscCurrent._positionSum;
delete gscCurrent._count;

// ============ GSC PREVIOUS ============
const gscPrevRaw = $('GSC - Last week').first().json;
const gscPrevRows = gscPrevRaw.rows || [];
const gscPrevious = gscPrevRows.reduce((acc, r) => {
  acc.clicks += r.clicks || 0;
  acc.impressions += r.impressions || 0;
  acc._ctrSum += r.ctr || 0;
  acc._positionSum += r.position || 0;
  acc._count += 1;
  return acc;
}, { clicks:0, impressions:0, _ctrSum:0, _positionSum:0, _count:0 });
gscPrevious.ctr = gscPrevious._count > 0 ? (gscPrevious._ctrSum / gscPrevious._count) : 0;
gscPrevious.position = gscPrevious._count > 0 ? (gscPrevious._positionSum / gscPrevious._count) : 0;
delete gscPrevious._ctrSum;
delete gscPrevious._positionSum;
delete gscPrevious._count;

// ============ GSC TOP QUERIES & PAGES ============
const topQueriesRaw = $('GSC - Top queries').first().json;
const topQueries = (topQueriesRaw.rows || []).slice(0, 10).map(r => ({
  query: r.keys[0],
  clicks: r.clicks,
  impressions: r.impressions,
  ctr: (r.ctr * 100).toFixed(2) + '%',
  position: r.position.toFixed(1)
}));

const topPagesRaw = $('GSC - Top pages').first().json;
const topPages = (topPagesRaw.rows || []).slice(0, 10).map(r => ({
  page: r.keys[0],
  clicks: r.clicks,
  impressions: r.impressions,
  ctr: (r.ctr * 100).toFixed(2) + '%',
  position: r.position.toFixed(1)
}));

// ============ SEGMETRICS REVENUE CURRENT ============
const smRevRaw = $('SegMetrics - Revenue this week').first().json;
const smRevReport = Array.isArray(smRevRaw) ? smRevRaw[0] : smRevRaw;
const smRevKpis = (smRevReport && smRevReport.kpis) || [];

function getKpi(kpis, key) {
  const k = kpis.find(x => x.key === key);
  return k ? k.value : 0;
}

const smRevenueCurrent = {
  customers: getKpi(smRevKpis, 'numOfCustomers'),
  revenue: getKpi(smRevKpis, 'revenue'),
  orders: getKpi(smRevKpis, 'numOfOrders'),
  aov: getKpi(smRevKpis, 'aov'),
  customer_value: getKpi(smRevKpis, 'customerValue')
};

// ============ SEGMETRICS REVENUE PREVIOUS ============
const smRevPrevRaw = $('SegMetrics - Revenue last week').first().json;
const smRevPrevReport = Array.isArray(smRevPrevRaw) ? smRevPrevRaw[0] : smRevPrevRaw;
const smRevPrevKpis = (smRevPrevReport && smRevPrevReport.kpis) || [];
const smRevenuePrevious = {
  customers: getKpi(smRevPrevKpis, 'numOfCustomers'),
  revenue: getKpi(smRevPrevKpis, 'revenue'),
  orders: getKpi(smRevPrevKpis, 'numOfOrders'),
  aov: getKpi(smRevPrevKpis, 'aov')
};

// ============ SEGMETRICS LEADS CURRENT ============
const smLeadsRaw = $('SegMetrics - Leads this week').first().json;
const smLeadsReport = Array.isArray(smLeadsRaw) ? smLeadsRaw[0] : smLeadsRaw;
const smLeadsKpis = (smLeadsReport && smLeadsReport.kpis) || [];
const smLeadsTable = (smLeadsReport && smLeadsReport.table && smLeadsReport.table.rows) || [];

const smLeadsCurrent = {
  leads: getKpi(smLeadsKpis, 'leads'),
  customers: getKpi(smLeadsKpis, 'numOfCustomers'),
  conversion_rate: getKpi(smLeadsKpis, 'conversionRate'),
  revenue: getKpi(smLeadsKpis, 'revenue'),
  lead_value: getKpi(smLeadsKpis, 'leadValue'),
  days_until_purchase: getKpi(smLeadsKpis, 'avg_days_until_purchase')
};

// Revenue by channel
const smChannels = smLeadsTable.map(r => ({
  channel: r.channel,
  leads: r.leads,
  customers: r.numOfCustomers,
  conversion_rate: (r.conversionRate || 0).toFixed(1) + '%',
  revenue: r.revenue,
  lead_value: (r.leadValue || 0).toFixed(2)
})).sort((a,b) => b.revenue - a.revenue);

// ============ SEGMETRICS LEADS PREVIOUS ============
const smLeadsPrevRaw = $('SegMetrics - Leads last week').first().json;
const smLeadsPrevReport = Array.isArray(smLeadsPrevRaw) ? smLeadsPrevRaw[0] : smLeadsPrevRaw;
const smLeadsPrevKpis = (smLeadsPrevReport && smLeadsPrevReport.kpis) || [];
const smLeadsPrevious = {
  leads: getKpi(smLeadsPrevKpis, 'leads'),
  customers: getKpi(smLeadsPrevKpis, 'numOfCustomers'),
  conversion_rate: getKpi(smLeadsPrevKpis, 'conversionRate'),
  revenue: getKpi(smLeadsPrevKpis, 'revenue')
};

// ============ SEGMETRICS TOP PRODUCTS ============
const smProductsTable = (smRevReport && smRevReport.table && smRevReport.table.rows) || [];
const topProducts = smProductsTable
  .filter(p => p.revenue > 0 && !p.product_name.toLowerCase().includes('discount'))
  .sort((a,b) => b.revenue - a.revenue)
  .slice(0, 5)
  .map(p => ({
    product: p.product_name,
    customers: p.numOfCustomers,
    revenue: p.revenue,
    price: p.amount
  }));

// ============ SEGMETRICS ADS ============
const smAdsRaw = $('SegMetrics - Ad spend').first().json;
const smAdsReport = Array.isArray(smAdsRaw) ? smAdsRaw[0] : smAdsRaw;
const smAdsKpis = (smAdsReport && smAdsReport.kpis) || [];
const smAds = {
  impressions: getKpi(smAdsKpis, 'adImpressions'),
  clicks: getKpi(smAdsKpis, 'adClicks'),
  spend: getKpi(smAdsKpis, 'adSpend'),
  roas: getKpi(smAdsKpis, 'adRoi')
};

// ============ UTM VALIDATION ============
const utm = $('Check UTM tagging').first().json;

// ============ BUILD FINAL PAYLOAD ============
const payload = {
  client: { name: config.client_name, website: config.website },
  period: {
    current_week: `${config.start_date} to ${config.end_date}`,
    previous_week: `${config.prev_start_date} to ${config.prev_end_date}`
  },
  ga4: {
    current: ga4Current,
    previous: ga4Previous,
    growth: {
      totalUsers: growth(ga4Current.totalUsers, ga4Previous.totalUsers),
      newUsers: growth(ga4Current.newUsers, ga4Previous.newUsers),
      sessions: growth(ga4Current.sessions, ga4Previous.sessions),
      pageViews: growth(ga4Current.screenPageViews, ga4Previous.screenPageViews),
      events: growth(ga4Current.eventCount, ga4Previous.eventCount),
      conversions: growth(ga4Current.conversions, ga4Previous.conversions)
    },
    channels: channels.slice(0, 7)
  },
  gsc: {
    current: gscCurrent,
    previous: gscPrevious,
    growth: {
      clicks: growth(gscCurrent.clicks, gscPrevious.clicks),
      impressions: growth(gscCurrent.impressions, gscPrevious.impressions),
      ctr: growth(gscCurrent.ctr, gscPrevious.ctr),
      position: growth(gscPrevious.position, gscCurrent.position)
    },
    top_queries: topQueries,
    top_pages: topPages
  },
  segmetrics: {
    revenue: {
      current: smRevenueCurrent,
      previous: smRevenuePrevious,
      growth: {
        revenue: growth(smRevenueCurrent.revenue, smRevenuePrevious.revenue),
        customers: growth(smRevenueCurrent.customers, smRevenuePrevious.customers),
        orders: growth(smRevenueCurrent.orders, smRevenuePrevious.orders),
        aov: growth(smRevenueCurrent.aov, smRevenuePrevious.aov)
      }
    },
    leads: {
      current: smLeadsCurrent,
      previous: smLeadsPrevious,
      growth: {
        leads: growth(smLeadsCurrent.leads, smLeadsPrevious.leads),
        customers: growth(smLeadsCurrent.customers, smLeadsPrevious.customers),
        conversion_rate: growth(smLeadsCurrent.conversion_rate, smLeadsPrevious.conversion_rate)
      },
      channels: smChannels.slice(0, 5)
    },
    top_products: topProducts,
    ads: smAds
  },
  utm_validation: utm
};

return [{ json: payload }];
